const page = await browser.getPage("main");
const errs=[]; page.on("pageerror",e=>errs.push(String(e)));
await page.setViewportSize({width:1400,height:800});
await page.goto("file:///private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.EirNrE/app/index.html");
await page.waitForTimeout(300);
const res = await page.evaluate(()=>{
  const out=[]; const S=window.__sim;
  function run(cfg,label,secs){
    Object.assign(S.settings,cfg);
    const t0=performance.now();
    S.launch();
    const n=Math.round(secs*480);
    let nan=false, maxDisp0=0;
    for(let i=0;i<n;i++){ S.step(); if(i===480){ // 1s in, before impact for slow? record
      } }
    const bricks=S.bodies().filter(b=>b.kind==='brick'); const car=S.car();
    let disp=0,maxv=0,bad=0; for(const b of bricks){ if(Math.hypot(b.x-b.ox,b.y-b.oy)>0.25)disp++; if(!isFinite(b.x)||!isFinite(b.y))bad++; }
    const st=S.state; out.push(label+": carX="+car.x.toFixed(3)+" vx="+car.vx.toFixed(2)+" disp="+disp+"/"+bricks.length+" nan="+bad+" ms="+(performance.now()-t0).toFixed(0)+" awake="+S.bodies().filter(b=>b.awake).length+" maxX="+Math.max(...bricks.map(b=>b.x)).toFixed(1));
  }
  const D={speed:22,cols:12,rows:8,layers:2,mass:2.5};
  run(D,"default a",8); run(D,"default b",8);
  run({speed:8,cols:12,rows:8,layers:5,mass:12},"slow heavy",10);
  run({speed:45,cols:24,rows:16,layers:5,mass:12},"max",8);
  run({speed:5,cols:24,rows:16,layers:5,mass:12},"slowest max wall",10);
  run({speed:12,cols:12,rows:8,layers:2,mass:2.5},"12 m/s default wall",8);
  run({speed:30,cols:4,rows:3,layers:1,mass:0.5},"tiny",6);
  return out;
});
console.log(res.join("\n")); console.log("errors",JSON.stringify(errs));
EOF

